insert into CHB_ASSETS_BASIS_DATA(VAL_ID, PROD_ID, ASSET_ID, VALUE_DATE, MDATE, POS_AMT, TDY_COST_AMT, TDY_FLOAT_INGPL, TDY_INTINCEXP, DELAY_PAY_AMT, REMARK, CREATE_TIME, UPDATE_TIME, CREATE_DEPT, ORG_CODE, DEPT_CODE, CREATE_USER, UPDATE_USER, STATUS, DATA_SOURCE,MD5PrimaryKey,CCY,TDY_INTADJEXP_ADD ) select VAL_ID, PROD_ID, ASSET_ID, VALUE_DATE, MDATE, POS_AMT, TDY_COST_AMT, TDY_FLOAT_INGPL, TDY_INTINCEXP, DELAY_PAY_AMT, REMARK, CREATE_TIME, UPDATE_TIME, CREATE_DEPT, ORG_CODE, DEPT_CODE, CREATE_USER, UPDATE_USER, STATUS, DATA_SOURCE,MD5PrimaryKey,CCY,TDY_INTADJEXP_ADD from ( select TEMP.* from (
SELECT #{item.valId,jdbcType=VARCHAR} VAL_ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.assetId,jdbcType=VARCHAR} ASSET_ID, #{item.valueDate,jdbcType=DATE} VALUE_DATE, #{item.mdate,jdbcType=DATE} MDATE, CAST(#{item.posAmt,jdbcType=DECIMAL} AS DECIMAL(30,2) )POS_AMT, CAST(#{item.tdyCostAmt,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_COST_AMT, CAST(#{item.tdyFloatIngpl,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_FLOAT_INGPL, CAST(#{item.tdyIntincexp,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_INTINCEXP, CAST(#{item.delayPayAmt,jdbcType=DECIMAL} AS DECIMAL(30,2) ) DELAY_PAY_AMT, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.status,jdbcType=VARCHAR} STATUS, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.md5primarykey,jdbcType=CHAR} MD5PRIMARYKEY ,#{item.ccy,jdbcType=VARCHAR} CCY ,CAST(#{item.tdyIntadjexpAdd,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_INTADJEXP_ADD FROM DUAL
) TEMP where not exists (select 1 from CHB_ASSETS_BASIS_DATA CII where CII.PROD_ID = TEMP.PROD_ID AND CII.ASSET_ID = TEMP.ASSET_ID AND CII.VALUE_DATE = TEMP.VALUE_DATE) ) de ;
UPDATE CHB_ASSETS_BASIS_DATA as A, ( select VAL_ID, PROD_ID, ASSET_ID, VALUE_DATE, MDATE, POS_AMT, TDY_COST_AMT, TDY_FLOAT_INGPL, TDY_INTINCEXP, DELAY_PAY_AMT, REMARK, CREATE_TIME, UPDATE_TIME, CREATE_DEPT, ORG_CODE, DEPT_CODE, CREATE_USER, UPDATE_USER, STATUS, DATA_SOURCE,MD5PrimaryKey,CCY,TDY_INTADJEXP_ADD from ( select TEMP.* from (
SELECT #{item.valId,jdbcType=VARCHAR} VAL_ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.assetId,jdbcType=VARCHAR} ASSET_ID, #{item.valueDate,jdbcType=DATE} VALUE_DATE, #{item.mdate,jdbcType=DATE} MDATE, CAST(#{item.posAmt,jdbcType=DECIMAL} AS DECIMAL(30,2) )POS_AMT, CAST(#{item.tdyCostAmt,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_COST_AMT, CAST(#{item.tdyFloatIngpl,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_FLOAT_INGPL, CAST(#{item.tdyIntincexp,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_INTINCEXP, CAST(#{item.delayPayAmt,jdbcType=DECIMAL} AS DECIMAL(30,2) ) DELAY_PAY_AMT, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.status,jdbcType=VARCHAR} STATUS, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.md5primarykey,jdbcType=CHAR} MD5PRIMARYKEY ,#{item.ccy,jdbcType=VARCHAR} CCY ,CAST(#{item.tdyIntadjexpAdd,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_INTADJEXP_ADD FROM DUAL
) TEMP ) de ) AS B SET A.VAL_ID = B.VAL_ID, A.MDATE = B.MDATE, A.POS_AMT = B.POS_AMT, A.TDY_COST_AMT = B.TDY_COST_AMT, A.TDY_FLOAT_INGPL = B.TDY_FLOAT_INGPL, A.TDY_INTINCEXP = B.TDY_INTINCEXP, A.DELAY_PAY_AMT = B.DELAY_PAY_AMT, A.REMARK = B.REMARK, A.CREATE_TIME = B.CREATE_TIME, A.UPDATE_TIME = B.UPDATE_TIME, A.CREATE_DEPT = B.CREATE_DEPT, A.ORG_CODE = B.ORG_CODE, A.DEPT_CODE = B.DEPT_CODE, A.CREATE_USER = B.CREATE_USER, A.UPDATE_USER = B.UPDATE_USER, A.STATUS = B.STATUS, A.DATA_SOURCE = B.DATA_SOURCE, A.MD5PRIMARYKEY = B.MD5PRIMARYKEY ,A.CCY = B.CCY ,A.TDY_INTADJEXP_ADD = B.TDY_INTADJEXP_ADD where A.PROD_ID = B.PROD_ID AND A.ASSET_ID = B.ASSET_ID AND A.VALUE_DATE = B.VALUE_DATE;

insert into CHB_ASSETS_BASIS_DATA_NOBTM(VAL_ID, PROD_ID, ASSET_ID, VALUE_DATE, MDATE, POS_AMT, TDY_COST_AMT, TDY_FLOAT_INGPL, TDY_INTINCEXP, DELAY_PAY_AMT, REMARK, CREATE_TIME, UPDATE_TIME, CREATE_DEPT, ORG_CODE, DEPT_CODE, CREATE_USER, UPDATE_USER, STATUS, DATA_SOURCE,MD5PrimaryKey,CCY,TDY_INTADJEXP_ADD) select VAL_ID, PROD_ID, ASSET_ID, VALUE_DATE, MDATE, POS_AMT, TDY_COST_AMT, TDY_FLOAT_INGPL, TDY_INTINCEXP, DELAY_PAY_AMT, REMARK, CREATE_TIME, UPDATE_TIME, CREATE_DEPT, ORG_CODE, DEPT_CODE, CREATE_USER, UPDATE_USER, STATUS, DATA_SOURCE,MD5PrimaryKey,CCY,TDY_INTADJEXP_ADD from ( select TEMP.* from (
SELECT #{item.valId,jdbcType=VARCHAR} VAL_ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.assetId,jdbcType=VARCHAR} ASSET_ID, #{item.valueDate,jdbcType=DATE} VALUE_DATE, #{item.mdate,jdbcType=DATE} MDATE, CAST(#{item.posAmt,jdbcType=DECIMAL} AS DECIMAL(30,2) ) POS_AMT, CAST(#{item.tdyCostAmt,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_COST_AMT, CAST(#{item.tdyFloatIngpl,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_FLOAT_INGPL, CAST(#{item.tdyIntincexp,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_INTINCEXP, CAST(#{item.delayPayAmt,jdbcType=DECIMAL} AS DECIMAL(30,2) ) DELAY_PAY_AMT, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.status,jdbcType=VARCHAR} STATUS, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.md5primarykey,jdbcType=CHAR} MD5PRIMARYKEY ,#{item.ccy,jdbcType=VARCHAR} CCY ,CAST(#{item.tdyIntadjexpAdd,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_INTADJEXP_ADD FROM DUAL
) TEMP where not exists (select 1 from CHB_ASSETS_BASIS_DATA_NOBTM CII where CII.PROD_ID = TEMP.PROD_ID AND CII.ASSET_ID = TEMP.ASSET_ID AND CII.VALUE_DATE = TEMP.VALUE_DATE) ) de ;
UPDATE CHB_ASSETS_BASIS_DATA_NOBTM as A, ( select VAL_ID, MDATE, POS_AMT, TDY_COST_AMT, TDY_FLOAT_INGPL, TDY_INTINCEXP, DELAY_PAY_AMT, REMARK, CREATE_TIME, UPDATE_TIME, CREATE_DEPT, ORG_CODE, DEPT_CODE, CREATE_USER, UPDATE_USER, STATUS, DATA_SOURCE, MD5PRIMARYKEY, CCY,TDY_INTADJEXP_ADD from ( select TEMP.* from (
SELECT #{item.valId,jdbcType=VARCHAR} VAL_ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.assetId,jdbcType=VARCHAR} ASSET_ID, #{item.valueDate,jdbcType=DATE} VALUE_DATE, #{item.mdate,jdbcType=DATE} MDATE, CAST(#{item.posAmt,jdbcType=DECIMAL} AS DECIMAL(30,2) ) POS_AMT, CAST(#{item.tdyCostAmt,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_COST_AMT, CAST(#{item.tdyFloatIngpl,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_FLOAT_INGPL, CAST(#{item.tdyIntincexp,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_INTINCEXP, CAST(#{item.delayPayAmt,jdbcType=DECIMAL} AS DECIMAL(30,2) ) DELAY_PAY_AMT, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.status,jdbcType=VARCHAR} STATUS, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.md5primarykey,jdbcType=CHAR} MD5PRIMARYKEY ,#{item.ccy,jdbcType=VARCHAR} CCY ,CAST(#{item.tdyIntadjexpAdd,jdbcType=DECIMAL} AS DECIMAL(30,2) ) TDY_INTADJEXP_ADD FROM DUAL
) TEMP ) de ) AS B set A.* = B.* where exists (select 1 from CHB_ASSETS_BASIS_DATA_NOBTM CII where CII.PROD_ID = TEMP.PROD_ID AND CII.ASSET_ID = TEMP.ASSET_ID AND CII.VALUE_DATE = TEMP.VALUE_DATE );

