mapper.select:
select t.*,T1.CHL_ID from ( select * from ( SELECT psv1.prod_id AS prod_id, /*产品代码*/ psv1.asset_id AS asset_id, /*资产代码*/ psv1.ccy AS ccy, /*币种*/ psv1.value_date AS value_date, /*日期*/ psv1.mdate AS mdate, /*资产到期日*/ SUM(ifnull(psv1.pos_amt,0)) AS pos_amt, /*当日持仓*/ SUM(ifnull(psv1.tdy_cost_amt,0)) AS tdy_cost_amt, /*当日成本*/ SUM(ifnull(psv1.tdy_float_ingpl,0)) AS tdy_float_ingpl, /*当日公允价值变动*/ SUM(ifnull(psv1.tdy_intincexp,0)) AS tdy_intincexp, /*当日累计应计利息余额*/ SUM(ifnull(psv1.delay_pay_amt,0)) AS delay_pay_amt, /*待清算款*/ MAX(psv1.update_time) AS update_time FROM ( SELECT c.finprod_market_id asset_id, /*资产代码*/ a.portfolio_id prod_id, /*产品代码*/ a.ccy ccy, /*币种*/ a.cdate value_date, /*日期*/ c.mdate mdate, /*资产到期日*/ a.share_amt pos_amt, /*当日持仓*/ a.dsc_cost_amt tdy_cost_amt, /*当日成本*/ a.tdy_float_ingpl tdy_float_ingpl, /*当日公允价值变动*/ a.tdy_intincexp tdy_intincexp, /*当日累计应计利息余额*/ a.delay_pay_amt delay_pay_amt, /*待清算款*/ ifnull(a.update_time,a.create_time) update_time FROM ptl_sec_valution a INNER JOIN fin_product b ON a.finprod_id = b.finprod_id LEFT JOIN fin_product c ON b.chl_finprod_id = c.finprod_id WHERE 1=1 AND b.chl_finprod_id IS NOT NULL AND DATE_FORMAT(a.cdate,'%Y-%m-%d')= #{batchTime,jdbcType= VARCHAR} AND exists( select 1 from FIN_PRODUCT_ADD fp3 where fp3.PORTFOLIO_ID = a.PORTFOLIO_ID) )psv1 GROUP BY psv1.asset_id, psv1.prod_id, psv1.ccy, psv1.value_date, psv1.mdate ) a where a.ASSET_ID is not null union all select * from ( select psv1.PROD_ID as PROD_ID, ifnull(ifnull(fpf.FINPROD_MARKET_ID,fp1.FINPROD_MARKET_ID),psv1.FINPROD_ID) as ASSET_ID, psv1.ccy, psv1.VALUE_DATE as VALUE_DATE, ifnull(fp1.MDATE,fp2.MDATE) as MDATE, sum(ifnull(psv1.POS_AMT,0)) as POS_AMT, sum(ifnull(psv1.TDY_COST_AMT,0)) as TDY_COST_AMT, sum(ifnull(psv1.TDY_FLOAT_INGPL,0)) as TDY_FLOAT_INGPL, sum(ifnull(psv1.TDY_INTINCEXP,0)) as TDY_INTINCEXP, sum(ifnull(psv1.DELAY_PAY_AMT,0)) as DELAY_PAY_AMT, max(psv1.UPDATE_TIME) UPDATE_TIME from ( select psv.PORTFOLIO_ID as PROD_ID, ifnull(ifnull(fp.P_FINPROD_ID,fp.FINPROD_ID),fp2.FINPROD_ID) as FINPROD_ID, psv.ccy, psv.CDATE as VALUE_DATE, (case fp.finprod_type when 'F01' then 100*psv.SHARE_AMT else psv.SHARE_AMT end) as POS_AMT, psv.DSC_COST_AMT as TDY_COST_AMT, psv.TDY_FLOAT_INGPL as TDY_FLOAT_INGPL, psv.TDY_INTINCEXP as TDY_INTINCEXP, psv.DELAY_PAY_AMT as DELAY_PAY_AMT, ifnull(psv.UPDATE_TIME,psv.CREATE_TIME) UPDATE_TIME from PTL_SEC_VALUTION psv left join FIN_PRODUCT fp on fp.FINPROD_ID = psv.FINPROD_ID and fp.chl_finprod_id is null left join FIN_TRADE_PRODUCT fp2 on fp2.FINPROD_ID = psv.FINPROD_ID and fp2.branch = 0 left join STL_SEC_ACCT_INFO info on info.sec_acct_id = psv.sec_acct_id where (psv.sec_acct_id='999999' or info.sec_acct_id is not null)
and DATE_FORMAT(psv.CDATE,'%Y-%m-%d')= #{batchTime,jdbcType=VARCHAR}
and exists( select 1 from FIN_PRODUCT_ADD fp3 where fp3.PORTFOLIO_ID = psv.PORTFOLIO_ID) ) psv1 left join FIN_PRODUCT fp1 on fp1.FINPROD_ID = psv1.FINPROD_ID left join FIN_PRODUCT fpf on fpf.FINPROD_ID = fp1.P_FINPROD_ID left join FIN_TRADE_PRODUCT fp2 on fp2.FINPROD_ID = psv1.FINPROD_ID and fp2.branch = 0
where 1=1 group by psv1.PROD_ID,psv1.VALUE_DATE,ifnull(fp1.MDATE,fp2.MDATE),ifnull(ifnull(fpf.FINPROD_MARKET_ID,fp1.FINPROD_MARKET_ID),psv1.FINPROD_ID),psv1.ccy ) a where a.ASSET_ID is not null) t inner join (select DISTINCT fp.finprod_market_id asset_id,fp1.finprod_market_id chl_id from fin_cash_info ca left join fin_product fp on FP.FINPROD_ID=CA.FINPROD_ID left join fin_product fp1 on FP1.FINPROD_ID=CA.CHL_FINPROD_ID left join fin_product_type tp on tp.FINPROD_ID=FP.FINPROD_ID where TP.TYPE_8 IN('F06','F03'
,'F05'
) and CA.CHL_FINPROD_ID is not null) t1 on T1.asset_id=t.asset_id

select min(EXERCISE_DATE) EXERCISE_DATE
from FIN_EXERCISE_PLAN
where FINPROD_ID = #{secid,jdbcType=VARCHAR}
and EXERCISE_DATE >= #{valueDate,jdbcType=DATE}
